BEGIN;
UPDATE branch_settings SET booking_policy_json=booking_policy_json||'{"earlyCheckInWarningMinutes":30,"lateArrivalWarningMinutes":15,"lateArrivalHardLimitMinutes":60,"allowLateCheckInOverride":true,"queueBufferMinutes":5}'::jsonb WHERE tenant_id='10000000-0000-4000-8000-000000000001';
ON CONFLICT(tenant_id,staff_id,skill_id) DO UPDATE SET proficiency_level=excluded.proficiency_level,status='ACTIVE';
UPDATE appointments SET status='IN_SERVICE' WHERE id='70000000-0000-4000-8000-000000000016';
UPDATE appointments SET checkout_ready=true WHERE id IN ('70000000-0000-4000-8000-000000000008','70000000-0000-4000-8000-000000000017','70000000-0000-4000-8000-000000000026');
COMMIT;
