INSERT INTO walk_in_status_history(tenant_id,walk_in_entry_id,from_status,to_status,actor_user_id,reason_code,note,request_id) SELECT tenant_id,id,NULL,status,created_by_user_id,'DETERMINISTIC_SEED',note,'seed:sprint5' FROM walk_in_entries w WHERE w.id::text LIKE '75000000-%' AND NOT EXISTS(SELECT 1 FROM walk_in_status_history h WHERE h.tenant_id=w.tenant_id AND h.walk_in_entry_id=w.id AND h.request_id='seed:sprint5');
